$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$lifecycle = Decode ""
$groupPage = Decode ""
$importOld = Decode "aW1wb3J0IHsgc3VwYWJhc2VBZG1pbiB9IGZyb20gIkAvbGliL3N1cGFiYXNlLWFkbWluIjs="
$importNew = Decode "aW1wb3J0IHsgc3VwYWJhc2VBZG1pbiB9IGZyb20gIkAvbGliL3N1cGFiYXNlLWFkbWluIjsKaW1wb3J0IHsKICBzeW5jQm9va2luZ0dyb3VwTGlmZWN5Y2xlLAp9IGZyb20gIkAvbGliL2Jvb2tpbmctZ3JvdXAtbGlmZWN5Y2xlIjsKCi8vIEtMWVhfR1JPVVBfVFJBQ0tJTkdfU1lOQ18xMl84Nw=="
$typeOld = Decode "ICBiYWJ5c2l0dGVyX2lkOiBzdHJpbmcgfCBudWxsOwogIHN0YXR1czogc3RyaW5nOw=="
$typeNew = Decode "ICBiYWJ5c2l0dGVyX2lkOiBzdHJpbmcgfCBudWxsOwogIGJvb2tpbmdfZ3JvdXBfaWQ6IHN0cmluZyB8IG51bGw7CiAgc3RhdHVzOiBzdHJpbmc7"
$selectOld = Decode "aWQsIHBhcmVudF9pZCwgcHJvdmlkZXJfaWQsIGJhYnlzaXR0ZXJfaWQsIHN0YXR1cywgcGF5bWVudF9zdGF0dXMsIHNlcnZpY2Vfc3RhdHVzLCBwcm92aWRlcl9maW5pc2hlZF9hdCwgY2xpZW50X2NvbmZpcm1lZF9hdA=="
$selectNew = Decode "aWQsIHBhcmVudF9pZCwgcHJvdmlkZXJfaWQsIGJhYnlzaXR0ZXJfaWQsIGJvb2tpbmdfZ3JvdXBfaWQsIHN0YXR1cywgcGF5bWVudF9zdGF0dXMsIHNlcnZpY2Vfc3RhdHVzLCBwcm92aWRlcl9maW5pc2hlZF9hdCwgY2xpZW50X2NvbmZpcm1lZF9hdA=="
$completionAnchor = Decode "ICAgICAgYXdhaXQgUHJvbWlzZS5hbGwobm90aWZpY2F0aW9ucyk7"
$completionNew = Decode "ICAgICAgYXdhaXQgUHJvbWlzZS5hbGwobm90aWZpY2F0aW9ucyk7CgogICAgICBpZiAoYm9va2luZy5ib29raW5nX2dyb3VwX2lkKSB7CiAgICAgICAgYXdhaXQgc3luY0Jvb2tpbmdHcm91cExpZmVjeWNsZSgKICAgICAgICAgIGJvb2tpbmcuYm9va2luZ19ncm91cF9pZAogICAgICAgICk7CiAgICAgIH0="

$lifecyclePath = Join-Path $root "lib\booking-group-lifecycle.ts"
$groupPagePath = Join-Path $root "app\booking-groups\[id]\page.tsx"
$trackingPath = Join-Path $root "app\api\bookings\tracking\route.ts"

foreach ($path in @($groupPagePath, $trackingPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "Fichier requis introuvable : $path"
    }
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

foreach ($path in @($groupPagePath, $trackingPath)) {
    Copy-Item -LiteralPath $path -Destination ($path + ".bak-12-87-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($lifecyclePath, $lifecycle, $utf8)
[System.IO.File]::WriteAllText($groupPagePath, $groupPage, $utf8)

$tracking = [System.IO.File]::ReadAllText($trackingPath)

if (-not $tracking.Contains("KLYX_GROUP_TRACKING_SYNC_12_87")) {
    if (-not $tracking.Contains($importOld)) {
        throw "12.87 : import tracking introuvable."
    }

    $tracking = $tracking.Replace($importOld, $importNew)

    if (-not $tracking.Contains($typeOld)) {
        throw "12.87 : type BookingRow tracking introuvable."
    }

    $tracking = $tracking.Replace($typeOld, $typeNew)

    if (-not $tracking.Contains($selectOld)) {
        throw "12.87 : select tracking introuvable."
    }

    $tracking = $tracking.Replace($selectOld, $selectNew)

    $clientBranch = $tracking.IndexOf(
        '    if (action === "client_confirmed") {'
    )

    if ($clientBranch -lt 0) {
        throw "12.87 : branche client_confirmed introuvable."
    }

    $completionIndex = $tracking.IndexOf($completionAnchor, $clientBranch)

    if ($completionIndex -lt 0) {
        throw "12.87 : fin notifications client introuvable."
    }

    $tracking = $tracking.Remove(
        $completionIndex,
        $completionAnchor.Length
    ).Insert(
        $completionIndex,
        $completionNew
    )
}

[System.IO.File]::WriteAllText($trackingPath, $tracking, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.87 APPLIQUE"
Write-Host "======================================"
Write-Host "Progression groupe : OK"
Write-Host "Suivi par creneau : OK"
Write-Host "Fin groupe synchronisee : OK"
Write-Host "Confirmation client conservee : OK"
Write-Host "Paiement automatique : NON"
Write-Host "======================================"
Write-Host ""
